public static int safeParseInt(String input, int maxLength, int defaultValue) {
    if (input == null || input.length() > maxLength || input.length() == 0) {
        return defaultValue;
    }
    try {
        return Integer.parseInt(input);
    } catch (NumberFormatException e) {
        return defaultValue;
    }
}

