public static int factorial(int n) {
    if (n < 0 || n > 20) throw new IllegalArgumentException("Input must be between 0 and 20");
    try {
        return n == 0 ? 1 : n * factorial(n - 1);
    } catch (StackOverflowError e) {
        throw new IllegalStateException("Recursion depth exceeded", e);
    }
}

