public static String sanitizeUsername(String input) {
    if (input == null || input.trim().isEmpty()) return "guest";
    String sanitized = input.replaceAll("[^a-zA-Z0-9]", "");
    return sanitized.length() > 16 ? sanitized.substring(0, 16) : sanitized;
}

