public static String secureSubstring(String input, int maxLength) {
    if (input == null || maxLength <= 0) return "";
    try {
        return input.substring(0, Math.min(input.length(), Math.min(maxLength, 1024)));
    } catch (Exception e) {
        return "";
    }
}

