public static Path resolveSafePath(String baseDir, String userInput) throws IOException {
    if (baseDir == null || userInput == null) throw new IllegalArgumentException("Null input");
    Path basePath = Paths.get(baseDir).normalize().toAbsolutePath();
    Path resolvedPath = basePath.resolve(userInput).normalize();
    if (!resolvedPath.startsWith(basePath)) throw new SecurityException("Path traversal attempt");
    return resolvedPath;
}

