public static int safeAdd(int a, int b) throws ArithmeticException {
    if (b > 0 ? a > Integer.MAX_VALUE - b : a < Integer.MIN_VALUE - b) {
        throw new ArithmeticException("Integer overflow");
    }
    return a + b;
}

