public static <T> T safeCast(Object obj, Class<T> clazz) {
    if (obj == null || !clazz.isInstance(obj)) {
        return null;
    }
    try {
        return clazz.cast(obj);
    } catch (ClassCastException e) {
        return null;
    }
}
